// Activity log level (ADR 0012): from "access" on, the user is told that opening folders and files is recorded; at "full" the
// app reports every 30 s what is open (folder, file in the editor) so a System Admin sees it live.
const activityLevel=ref('minimal'),activityNotice=computed(()=>activityLevel.value==='access'||activityLevel.value==='full')
function presence(){if(activityLevel.value!=='full'||!user.value||disposed||globalThis.document?.hidden||!root.value)return;const e=editor.value;void request('/activity/presence',{method:'POST',body:JSON.stringify({root:e?.root??root.value,rootName:rootName.value,path:e?e.entry.path.split('/').slice(0,-1).join('/'):path.value,file:e?.entry.path??''})}).catch(()=>{})}
const beat=setInterval(presence,30000)
const sharing=ref({enabled:false,base:'',port:''}),received=ref<Grant[]>([]),outgoing=ref<{grants:Grant[];links:Link[]}>({grants:[],links:[]})
const shareTarget=ref<{path:string;name:string;dir:boolean}|null>(null)
// An item shared with the user opens as its own root "shared:<grant>": writable only for a folder shared to edit.
const sharedRoots=computed(()=>received.value.map(g=>({id:'shared:'+g.id,kind:'share',name:g.name,access:g.dir&&g.permission==='edit'?'write':'read',organization:g.owner}) as Root))
const allRoots=computed(()=>[...roots.value,...sharedRoots.value])
const findRoot=(id:string)=>allRoots.value.find(r=>r.id===id)
async function loadReceived(){try{received.value=(await request<{items:Grant[]}>('/sharing/received')).items}catch{received.value=[]}}
async function loadOutgoing(){if(!sharing.value.enabled)return;try{const r=await request<{grants:Grant[];links:Link[]}>('/sharing');outgoing.value={grants:r.grants,links:r.links}}catch{outgoing.value={grants:[],links:[]}}}
const sharedPaths=computed(()=>new Set([...outgoing.value.grants,...outgoing.value.links].map(x=>x.path)))
// Shared items of the home, one row per item with its people and links.
const outgoingRows=computed(()=>{const rows=new Map<string,{path:string;name:string;dir:boolean;people:number;links:number}>();for(const x of [...outgoing.value.grants,...outgoing.value.links]){const row=rows.get(x.path)??{path:x.path,name:x.name||baseName(x.path),dir:x.dir,people:0,links:0};if('token' in x)row.links++;else row.people++;rows.set(x.path,row)}return [...rows.values()].filter(r=>lower(r.name).includes(lower(query.value))).sort((a,b)=>a.path.localeCompare(b.path))})
const receivedRows=computed(()=>received.value.filter(g=>lower(g.name).includes(lower(query.value))||lower(g.owner).includes(lower(query.value))))
// Links live on the Files origin; embedded in the Desktop the page's host with the Files port is used.
const publicURL=(token:string)=>(sharing.value.base||(props.embedded?location.protocol+'//'+location.hostname+(sharing.value.port?':'+sharing.value.port:''):location.origin)).replace(/\/$/,'')+'/s/'+token
function share(entry:Entry|null){if(!entry||root.value!=='personal'||(entry.kind!=='file'&&entry.kind!=='folder'))return;shareTarget.value={path:entry.path,name:entry.name,dir:entry.kind==='folder'}}
