const baseName=(p:string)=>p.split('/').at(-1)||p,parentOf=(p:string)=>p.split('/').slice(0,-1).join('/'),join=(...parts:string[])=>parts.filter(Boolean).join('/')
const action=ref<'mkdir'|'rename'|'move'|'trash'|'remove'|'purge'|'empty'|null>(null),actionName=ref(''),busy=ref(false)
const editor=ref<{entry:Entry;content:string;original:string;etag:string;root:string}|null>(null),editorBusy=ref(false)
const input=ref<HTMLInputElement|null>(null),folderInput=ref<HTMLInputElement|null>(null)
// A transfer is an upload (file, xhr) or a background copy job on the server (jobId).
type Transfer={id:number;name:string;progress:number;status:string;error:string;root:string;path:string;file?:File;xhr?:XMLHttpRequest;jobId?:string}
const transfers=ref<Transfer[]>([]),showTransfers=ref(false)
let loadRevision=0
let disposed=false
const lower=(value:string)=>value.toLocaleLowerCase(host.profile.value.locale)
// Sorting (persisted): folders first, then by name, size, date or type; recent files keep their newest-first order.
type SortKey='name'|'size'|'modified'|'type'
const sortKey=ref<SortKey>((localStorage.getItem('drive.sort')?.split(':')[0] as SortKey)||'name'),sortDesc=ref(localStorage.getItem('drive.sort')?.endsWith(':desc')??false)
watch([sortKey,sortDesc],()=>localStorage.setItem('drive.sort',sortKey.value+(sortDesc.value?':desc':':asc')))
const extension=(name:string)=>name.includes('.')?lower(name.slice(name.lastIndexOf('.')+1)):''
function compare(a:Entry,b:Entry){if((a.kind==='folder')!==(b.kind==='folder'))return a.kind==='folder'?-1:1;const byName=a.name.localeCompare(b.name,host.profile.value.locale,{numeric:true,sensitivity:'base'});const v=sortKey.value==='size'?a.size-b.size:sortKey.value==='modified'?Date.parse(a.modified)-Date.parse(b.modified):sortKey.value==='type'?extension(a.name).localeCompare(extension(b.name)):0;return (v||byName)*(sortDesc.value?-1:1)}
const display=computed(()=>{const list=entries.value.filter(e=>(hidden.value||!e.name.startsWith('.'))&&lower(e.name).includes(lower(query.value)));return special.value==='recent'?list:list.sort(compare)})
const shortDate=(value:string)=>host.i18n.formatDate(new Date(value),{day:'2-digit',month:'2-digit',year:'numeric'})
const longDate=(value:string)=>host.i18n.formatDate(new Date(value),{dateStyle:'medium',timeStyle:'short'})
const current=computed(()=>findRoot(root.value))
const rootLabel=(r?:Root)=>r?.kind==='share'?r.name??'':r?.id==='system'?t('files.roots.system'):t('files.roots.personal'),rootName=computed(()=>rootLabel(current.value))
const readOnly=computed(()=>current.value?.access==='read')
const isShare=computed(()=>root.value.startsWith('share:')),isGrant=computed(()=>root.value.startsWith('shared:'))
const listView=computed(()=>special.value==='favorites'||special.value==='received'||special.value==='outgoing')
// Quota folders of the open Shared Folder (Q3): the innermost one around the current path is shown with its usage.
type QuotaFolder={path:string;usage:{limitBytes:number|null;usedBytes:number;measured:boolean}}
const quotaFolders=ref<QuotaFolder[]>([])
const quotaFolder=computed(()=>trash.value?undefined:quotaFolders.value.filter(f=>path.value===f.path||path.value.startsWith(f.path+'/')).sort((a,b)=>b.path.length-a.path.length)[0])
async function loadQuotaFolders(){if(!isShare.value){quotaFolders.value=[];return}try{quotaFolders.value=(await request<{items:QuotaFolder[]}>('/quota-folders?root='+encodeURIComponent(root.value))).items}catch{quotaFolders.value=[]}}
// Trash belongs to the current home or Shared Folder; the host system root has none.
// Shared Folders grouped by owning organization (ADR 0008); a heading appears only when they come from more than one.
const navRoots=computed(()=>{const shares=roots.value.filter(r=>r.kind==='share').sort((a,b)=>(a.organization??'').localeCompare(b.organization??'')||rootLabel(a).localeCompare(rootLabel(b))),many=new Set(shares.map(r=>r.organizationId)).size>1;return [...roots.value.filter(r=>r.kind==='home'),...shares,...roots.value.filter(r=>r.kind==='system')].map((r,i,all)=>({root:r,group:many&&r.kind==='share'&&(all[i-1]?.kind!=='share'||all[i-1].organizationId!==r.organizationId)?r.organization??'':''}))})
const trashRoot=computed(()=>root.value!=='system'&&!isGrant.value?root.value:roots.value.find(r=>r.id!=='system')?.id??'')
const crumbs=computed(()=>path.value.split('/').filter(Boolean))
const headingTitle=computed(()=>trash.value?t('files.trash.title'):special.value==='recent'?t('files.recent.title'):special.value==='favorites'?t('files.favorites.title'):special.value==='received'?t('files.received.title'):special.value==='outgoing'?t('files.outgoing.title'):special.value==='search'?t('files.search.title',{query:searchTerm.value}):crumbs.value.at(-1)||rootName.value)
const headingHint=computed(()=>trash.value?t('files.trash.hint'):special.value==='recent'?t('files.recent.hint',{root:rootName.value}):special.value==='favorites'?t('files.favorites.hint'):special.value==='received'?t('files.received.hint'):special.value==='outgoing'?t('files.outgoing.hint'):special.value==='search'?t('files.search.hint',{folder:crumbs.value.at(-1)||rootName.value}):root.value==='system'?t('files.heading.systemHint'):isGrant.value?t(readOnly.value?'files.received.readHint':'files.received.editHint',{owner:current.value?.organization??''}):isShare.value?t(readOnly.value?'files.roots.shareReadHint':'files.roots.shareHint'):t('files.heading.personalHint'))
const selectedItem=computed(()=>trash.value?selectedTrash.value:selected.value)
const dirty=computed(()=>!!editor.value&&editor.value.content!==editor.value.original)
const modalOpen=computed(()=>!!action.value||!!editor.value||!!shareTarget.value)
let dialogFrame=0
const dialogBounds=ref({left:0,top:0,width:0,height:0})
function trackDialog(){if(!props.embedded||!modalOpen.value||!props.active||disposed)return;const rect=appRoot.value?.getBoundingClientRect();if(rect){const next={left:rect.left,top:rect.top,width:rect.width,height:rect.height};if(JSON.stringify(next)!==JSON.stringify(dialogBounds.value))dialogBounds.value=next}dialogFrame=requestAnimationFrame(trackDialog)}
let priorFocus:HTMLElement|null=null
watch([modalOpen,()=>props.active],async ([value,active])=>{cancelAnimationFrame(dialogFrame);if(!active)return;if(value)priorFocus=document.activeElement as HTMLElement|null;await nextTick();if(value)trackDialog();if(value)document.querySelector<HTMLElement>('[aria-modal="true"] input, [aria-modal="true"] textarea, [aria-modal="true"] button')?.focus();else if(priorFocus?.isConnected)priorFocus.focus()})
function modalKeyboard(e:KeyboardEvent){if(!appVisible())return;if(!modalOpen.value)return;if(e.key==='Escape'&&!busy.value&&!editorBusy.value){if(shareTarget.value)closeShare();else if(editor.value)closeEditor();else action.value=null}if(e.key==='Tab'){const nodes=[...document.querySelectorAll<HTMLElement>('[aria-modal="true"] button, [aria-modal="true"] input, [aria-modal="true"] textarea, [aria-modal="true"] select')].filter(el=>!el.hasAttribute('disabled')&&el.getClientRects().length);const first=nodes[0],last=nodes.at(-1);if(first&&(e.shiftKey?document.activeElement===first:document.activeElement===last)){e.preventDefault();(e.shiftKey?last:first)?.focus()}}}
const activeTransfers=computed(()=>transfers.value.filter(t=>t.status==='uploading'||t.status==='queued').length)
// Only uploads stop with the page; copy jobs keep running on the server.
const activeUploads=computed(()=>transfers.value.filter(t=>t.file&&(t.status==='uploading'||t.status==='queued')).length)
function notify(message:string){notice.value=message;setTimeout(()=>notice.value='',6000)}
async function init(){const session=await request<{user:User;csrfToken:string;passwordChangeRequired?:boolean}>('/session');user.value=session.user;setCSRF(session.csrfToken);await host.loadProfile(request);passwordChange.value=!!session.passwordChangeRequired;if(passwordChange.value)return;await loadRoots();void loadFavorites();await load()}
async function login(){loginBusy.value=true;error.value='';try{const session=await request<{user:User;csrfToken:string;passwordChangeRequired?:boolean}>('/login',{method:'POST',body:JSON.stringify({username:loginName.value,password:loginPassword.value})});loginPassword.value='';user.value=session.user;setCSRF(session.csrfToken);await host.loadProfile(request);passwordChange.value=!!session.passwordChangeRequired;if(passwordChange.value)return;await loadRoots();await load()}catch(e){error.value=message(e)}finally{loginBusy.value=false}}
async function logout(){if(activeUploads.value&&!confirm(t('files.confirm.logoutUploads')))return;if(dirty.value&&!confirm(t('files.confirm.logoutDraft')))return;try{await request('/logout',{method:'POST',body:'{}'});transfers.value.forEach(t=>t.xhr?.abort());transfers.value=[];editor.value=null;user.value=null;entries.value=[];selected.value=null;selectedTrash.value=null;root.value='personal';path.value='';trash.value=false;setCSRF('')}catch(e){error.value=message(e)}}
// Stable error codes only (app standard row 8): Files codes from this catalog, the rest from the SDK.
function message(e:unknown){const key='files.errors.'+(e instanceof ApiError?e.code:'');return key in catalogs['vi-VN']?t(key):host.errorMessage(e)}
async function load(){if(disposed)return;if(!root.value){entries.value=[];trashItems.value=[];return}void loadQuotaFolders();if(root.value==='personal'&&!special.value)void loadOutgoing();const revision=++loadRevision;loading.value=true;error.value='';selected.value=null;selectedPaths.value=[];selectedTrash.value=null;try{if(trash.value){const result=await request<TrashItem[]>(endpoint('trash',root.value,''));if(revision===loadRevision)trashItems.value=result}else if(special.value==='favorites'){await loadFavorites();if(revision===loadRevision)entries.value=[]}else if(special.value==='received'){await loadReceived();if(revision===loadRevision)entries.value=[]}else if(special.value==='outgoing'){await loadOutgoing();if(revision===loadRevision)entries.value=[]}else if(special.value==='recent'||special.value==='search'){const result=await request<{entries:Entry[];truncated:boolean}>(endpoint(special.value,root.value,path.value)+(special.value==='search'?'&q='+encodeURIComponent(searchTerm.value):''));if(revision===loadRevision){entries.value=result.entries;truncated.value=result.truncated}}else{const result=await client.list(root.value,path.value,request);if(revision===loadRevision)entries.value=result}}catch(e){if(revision===loadRevision){entries.value=[];trashItems.value=[];error.value=message(e)}}finally{if(revision===loadRevision)loading.value=false}}
function navigate(next:string){history.value.push(path.value);path.value=next;special.value='';query.value='';void load()}
function switchRoot(id:string){root.value=id;path.value='';trash.value=false;special.value='';history.value=[];query.value='';void load()}
function openTrash(){if(!trashRoot.value)return;root.value=trashRoot.value;path.value='';trash.value=true;special.value='';query.value='';void load()}
// Recent files of the current root (the home when the host system root is open); favorites span every root.
function openRecent(){if(!trashRoot.value)return;root.value=trashRoot.value;path.value='';trash.value=false;special.value='recent';query.value='';void load()}
function openFavorites(){trash.value=false;special.value='favorites';query.value='';void load()}
function openSharing(view:'received'|'outgoing'){trash.value=false;special.value=view;query.value='';void load()}
function openReceived(g:Grant){switchRoot('shared:'+g.id)}
async function openOutgoing(row:{path:string;name:string;dir:boolean}){shareTarget.value={path:row.path,name:row.name,dir:row.dir}}
// Enter in the search box searches the current folder and its subfolders on the server; clearing it returns.
function runSearch(){const q=query.value.trim();if(!q||trash.value||listView.value||!root.value)return;if(special.value==='recent'){special.value='';path.value=''}special.value='search';searchTerm.value=q;void load()}
watch(query,value=>{if(!value&&special.value==='search'){special.value='';void load()}})
async function loadFavorites(){try{favorites.value=(await request<{items:Favorite[]}>('/favorites')).items}catch{favorites.value=[]}}
async function toggleFavorite(entry:Entry|null){if(!entry)return;const on=isFavorite(entry),body={root:root.value,path:entry.path,dir:entry.kind==='folder'};try{await request(on?'/favorites/remove':'/favorites',{method:'POST',body:JSON.stringify(body)});notify(t(on?'files.notice.favoriteRemoved':'files.notice.favoriteAdded',{name:entry.name}));await loadFavorites()}catch(e){error.value=message(e)}}
async function removeFavorite(f:Favorite){try{await request('/favorites/remove',{method:'POST',body:JSON.stringify({root:f.root,path:f.path})});await loadFavorites()}catch(e){error.value=message(e)}}
// A favorite folder opens; a favorite file opens its folder with the file selected.
async function openFavorite(f:Favorite){root.value=f.root;trash.value=false;special.value='';query.value='';history.value=[];path.value=f.dir?f.path:parentOf(f.path);await load();const found=entries.value.find(e=>e.path===f.path);if(!f.dir&&found)choose(found)}
const favoriteRows=computed(()=>favorites.value.filter(f=>lower(baseName(f.path)).includes(lower(query.value))))
function choose(entry:Entry,event?:MouseEvent){
 if(event?.shiftKey&&selectionAnchor){const a=display.value.findIndex(e=>e.path===selectionAnchor),b=display.value.findIndex(e=>e.path===entry.path);selectedPaths.value=display.value.slice(Math.max(0,Math.min(a,b)),Math.max(a,b)+1).map(e=>e.path)}
 else if(event?.ctrlKey||event?.metaKey){selectedPaths.value=selectedPaths.value.includes(entry.path)?selectedPaths.value.filter(p=>p!==entry.path):[...selectedPaths.value,entry.path]}
 else selectedPaths.value=[entry.path]
 selected.value=selectedPaths.value.includes(entry.path)?entry:selectedEntries.value[0]||null;selectionAnchor=entry.path
}
function open(entry:Entry){if(entry.kind==='folder')navigate(entry.path);else if(entry.kind==='file')void openText(entry);else notify(t('files.notice.unsupportedOpen'))}
function setView(value:string){view.value=value;localStorage.setItem('drive.view',value)}
function begin(value:NonNullable<typeof action.value>){if((value==='rename'||value==='move')&&selectedPaths.value.length!==1)return;if(value!=='mkdir'&&value!=='empty'&&!(value==='purge'?selectedTrash.value:selected.value))return;action.value=value;actionName.value=value==='rename'?selected.value!.name:value==='move'?selected.value!.path:''}
async function submitAction(){if(!action.value)return;busy.value=true;error.value='';try{if(action.value==='purge'||action.value==='empty'){const result=await request<{freedBytes:number}>(endpoint(action.value==='purge'?'trash-delete':'empty-trash',root.value,''),{method:'POST',body:JSON.stringify(action.value==='purge'?{id:selectedTrash.value!.id}:{})});action.value=null;notify(t('files.notice.freed',{size:quotaSize(result.freedBytes)}));await load();await loadRoots().catch(()=>{});return}if(action.value==='trash'||action.value==='remove'){const targets=selectedEntries.value.slice();const failures:string[]=[];for(const item of targets){try{await request(endpoint(action.value,root.value,item.path),{method:'POST',body:JSON.stringify(action.value==='remove'?{confirm:true}:{})})}catch(e){failures.push(item.name+': '+message(e))}}action.value=null;await load();if(failures.length)error.value=failures.join(' · ');else notify(t('files.notice.processed',{count:targets.length}));return}const target=action.value==='mkdir'?path.value:selected.value!.path;await request(endpoint(action.value,root.value,target),{method:'POST',body:JSON.stringify(action.value==='move'?{destination:actionName.value}:{name:actionName.value})});action.value=null;notify(t('files.notice.done'));await load()}catch(e){error.value=message(e)}finally{busy.value=false}}
async function restore(){if(!selectedTrash.value)return;try{await request(endpoint('restore',root.value,''),{method:'POST',body:JSON.stringify({id:selectedTrash.value.id})});notify(t('files.notice.restored'));await load()}catch(e){error.value=message(e)}}
async function openText(entry:Entry){if(dirty.value&&!confirm(t('files.confirm.discardOpen')))return;editorBusy.value=true;error.value='';const editorRoot=root.value;try{const result=await request<{content:string;etag:string}>(endpoint('text',editorRoot,entry.path));editor.value={entry,content:result.content,original:result.content,etag:result.etag,root:editorRoot}}catch(e){error.value=message(e)}finally{editorBusy.value=false}}
function closeEditor(){if(dirty.value&&!confirm(t('files.confirm.discard')))return;editor.value=null}
async function saveText(){if(!editor.value||editorBusy.value)return;const state=editor.value;if(state.root==='system'&&!confirm(t('files.confirm.saveSystem',{path:state.entry.path})))return;editorBusy.value=true;try{const result=await request<{backup:string}>(endpoint('save-text',state.root,state.entry.path),{method:'POST',headers:{'If-Match':state.etag},body:JSON.stringify({content:state.content})});state.original=state.content;const fresh=await request<{etag:string}>(endpoint('text',state.root,state.entry.path));state.etag=fresh.etag;notify(t('files.notice.saved',{backup:result.backup}));await load()}catch(e){error.value=message(e)}finally{editorBusy.value=false}}
// One file downloads as it is; a folder or several items download as one ZIP streamed by the server.
function download(){const items=selectedEntries.value.filter(e=>e.kind==='file'||e.kind==='folder');if(!items.length)return;location.href=items.length===1&&items[0].kind==='file'?downloadURL(root.value,items[0].path):client.archiveURL(root.value,items.map(e=>e.path))}
async function startTransfer(t:Transfer){if(disposed||!t.file)return;t.status='uploading';t.error='';t.progress=0;try{const handle=upload(t.root,t.path,t.file,p=>t.progress=p);t.xhr=handle.xhr;await handle.done;t.status='done';t.xhr=undefined;if(root.value===t.root&&path.value===t.path&&!trash.value)await load()}catch(e){t.status='error';t.error=message(e);t.xhr=undefined}}
// A folder copy (or a file over 128 MB) is answered with a durable job (202); the panel polls it until it ends.
function jobStatus(t:Transfer,job:Job){t.progress=job.progress.total?Math.round(job.progress.completed/job.progress.total*100):0;t.status=({queued:'queued',running:'uploading',succeeded:'done',failed:'error',cancelled:'cancelled'} as Record<string,string>)[job.state];t.error=job.error?message(new ApiError(0,{code:job.error.code})):''}
async function trackJob(name:string,targetRoot:string,targetPath:string,job:Job){const id=Date.now()+Math.random();transfers.value.push({id,name,progress:0,status:'queued',error:'',root:targetRoot,path:targetPath,jobId:job.id});const t=transfers.value.find(x=>x.id===id)!;showTransfers.value=true;jobStatus(t,job);while(!disposed&&user.value&&(t.status==='queued'||t.status==='uploading')){await new Promise(r=>setTimeout(r,1500));try{jobStatus(t,await request<Job>(`/jobs/${job.id}`))}catch(e){t.status='error';t.error=message(e)}}if(t.status==='done'&&root.value===t.root&&path.value===t.path&&!trash.value)await load()}
function jobText(job:Transfer){return job.status==='error'?job.error:job.status==='done'?t('files.jobs.done'):job.status==='cancelled'?t('files.jobs.cancelled'):job.status==='queued'?t('files.jobs.queued'):t('files.jobs.copying',{progress:job.progress})}
async function cancelJob(t:Transfer){try{await request(`/jobs/${t.jobId}/cancel`,{method:'POST',body:'{}'})}catch(e){error.value=message(e)}}
// Uploads keep the folder structure of a dropped or chosen folder: its folders are created level by level first.
type UploadItem={file:File;dir:string}
async function queue(files:FileList|File[]|null){if(!files)return;await queueItems(Array.from(files).map(file=>({file,dir:parentOf(file.webkitRelativePath||'')})),[])}
async function queueItems(items:UploadItem[],emptyDirs:string[]){if(trash.value||special.value||disposed||!root.value)return;if(readOnly.value){notify(t('files.share.readOnly'));return}if(items.length>10000){notify(t('files.notice.uploadLimit'));return}const targetRoot=root.value,targetPath=path.value;showTransfers.value=true
 const dirs=new Set<string>();for(const d of [...emptyDirs,...items.map(i=>i.dir)])for(let p=d;p;p=parentOf(p))dirs.add(p)
 for(const d of [...dirs].sort((a,b)=>a.split('/').length-b.split('/').length)){try{await request(endpoint('mkdir',targetRoot,join(targetPath,parentOf(d))),{method:'POST',body:JSON.stringify({name:baseName(d)})})}catch(e){if(!(e instanceof ApiError&&e.code==='FILES_EXISTS')){error.value=baseName(d)+': '+message(e);return}}}
 if(dirs.size&&root.value===targetRoot&&path.value===targetPath)await load()
 const ids:number[]=[];for(const {file,dir} of items){if(file.size>128*1024*1024){error.value=t('files.notice.tooLarge',{name:file.name});continue}const id=Date.now()+Math.random();transfers.value.push({id,name:join(dir,file.name),progress:0,status:'queued',error:'',root:targetRoot,path:join(targetPath,dir),file});ids.push(id)}for(const id of ids){if(disposed||!user.value)break;const t=transfers.value.find(t=>t.id===id);if(t)await startTransfer(t)}if(input.value)input.value.value='';if(folderInput.value)folderInput.value.value=''}
// Dropped folders are read with the File System entries API; the entries must be taken before the first await.
async function dropped(data:DataTransfer){const roots=[...data.items].map(i=>i.webkitGetAsEntry?.()).filter((e):e is FileSystemEntry=>!!e);if(!roots.some(e=>e.isDirectory))return queue([...data.files]);const items:UploadItem[]=[],dirs:string[]=[]
 const walk=async(entry:FileSystemEntry,dir:string):Promise<void>=>{if(entry.isFile){items.push({file:await new Promise<File>((ok,fail)=>(entry as FileSystemFileEntry).file(ok,fail)),dir});return}if(!entry.isDirectory)return;const sub=join(dir,entry.name),reader=(entry as FileSystemDirectoryEntry).createReader();dirs.push(sub);for(;;){const batch=await new Promise<FileSystemEntry[]>((ok,fail)=>reader.readEntries(ok,fail));if(!batch.length)break;for(const child of batch)await walk(child,sub)}}
 try{for(const entry of roots)await walk(entry,'')}catch(e){error.value=message(e);return}await queueItems(items,dirs)}
// Dragging items onto a folder or a breadcrumb moves them there (same root); a drag from outside the page uploads.
const dragType='application/x-minhanos-files',dropTarget=ref<string|null>(null)
let dragging:{root:string;paths:string[]}|null=null
function dragStart(event:DragEvent,entry:Entry){if(readOnly.value||trash.value||entry.kind==='special'||!event.dataTransfer){event.preventDefault();return}if(!selectedPaths.value.includes(entry.path))choose(entry);dragging={root:root.value,paths:[...selectedPaths.value]};event.dataTransfer.setData(dragType,dragging.paths.join('\n'));event.dataTransfer.effectAllowed='move'}
function dragEnd(){dragging=null;dropTarget.value=null}
const canDrop=(target:string)=>!!dragging&&dragging.root===root.value&&!dragging.paths.some(p=>target===p||target.startsWith(p+'/')||parentOf(p)===target)
function dragOver(event:DragEvent,target:string){if(!canDrop(target))return;event.preventDefault();event.stopPropagation();if(event.dataTransfer)event.dataTransfer.dropEffect='move';dropTarget.value=target}
async function dropMove(event:DragEvent,target:string){if(!dragging)return;if(busy.value){event.preventDefault();dragEnd();return}event.preventDefault();event.stopPropagation();const items=canDrop(target)?dragging.paths:[];dragEnd();if(!items.length)return;busy.value=true;const failed:string[]=[];for(const p of items){try{await request(endpoint('move',root.value,p),{method:'POST',body:JSON.stringify({destination:join(target,baseName(p))})})}catch(e){failed.push(baseName(p)+': '+message(e))}}busy.value=false;await load();if(failed.length)error.value=failed.join(' · ');else notify(t('files.notice.moved',{count:items.length}))}
function drop(event:DragEvent){event.preventDefault();if(dragging||event.dataTransfer?.types.includes(dragType)){dragEnd();return}if(event.dataTransfer)void dropped(event.dataTransfer)}
onMounted(async()=>{try{await init()}catch(e){if(!(e instanceof ApiError&&e.code==='AUTH_REQUIRED'))error.value=message(e)}finally{ready.value=true}})
function beforeUnload(e:BeforeUnloadEvent){if(activeUploads.value||dirty.value){e.preventDefault();e.returnValue=''}}
function appVisible(){return props.active&&!!appRoot.value?.getClientRects().length}
function canClose(){return !(activeUploads.value||dirty.value)||confirm(t('files.confirm.close'))}
defineExpose({canClose})
onMounted(()=>{globalThis.addEventListener('keydown',modalKeyboard);globalThis.addEventListener('keydown',fileKeyboard);globalThis.addEventListener('beforeunload',beforeUnload);globalThis.addEventListener('resize',dismissMenu);globalThis.addEventListener('scroll',scrollMenu,true)})
watch([root,path,()=>editor.value?.entry.path],()=>presence())
onBeforeUnmount(()=>{disposed=true;clearInterval(beat);cancelAnimationFrame(dialogFrame);globalThis.removeEventListener('keydown',modalKeyboard);globalThis.removeEventListener('keydown',fileKeyboard);globalThis.removeEventListener('beforeunload',beforeUnload);globalThis.removeEventListener('resize',dismissMenu);globalThis.removeEventListener('scroll',scrollMenu,true);transfers.value.forEach(t=>t.xhr?.abort());menu.value=null})
watch([query,hidden],()=>{selected.value=null;selectedPaths.value=[];selectedTrash.value=null;dismissMenu()})
const menuActions=computed(()=>fileActions({kind:trash.value&&(menu.value?.blank||!selectedTrash.value)?'trash-blank':menu.value?.blank||(!selected.value&&!selectedTrash.value)?'empty':trash.value?'trash':selected.value?.kind==='folder'?'folder':selected.value?.kind==='file'?'file':'special',count:trash.value?trashItems.value.length:selectedEntries.value.length,system:root.value==='system',canPaste:!!clipboard.value&&clipboard.value.root===root.value,canCopy:selectedEntries.value.length>0&&selectedEntries.value.every(e=>e.kind==='file'||e.kind==='folder'),readOnly:readOnly.value||(!!menu.value?.blank&&!!special.value),favorite:isFavorite(selected.value),shareable:sharing.value.enabled&&root.value==='personal'&&!special.value},t))
const actionIcons={open:FolderOpen,download:Download,copy:Copy,cut:Scissors,paste:ClipboardPaste,rename:Pencil,move:MoveRight,delete:Trash2,properties:Info,restore:RotateCcw,mkdir:FolderPlus,upload:Upload,refresh:RefreshCw,grid:Grid2X2,list:List,'select-all':Check,favorite:Star,purge:Trash2,'empty-trash':Trash2,'upload-folder':FolderUp,share:Share2}
function scrollMenu(e:Event){if(menuElement.value?.contains(e.target as Node))return;dismissMenu()}
watch(()=>props.active,active=>{if(!active)dismissMenu()})
function dismissMenu(){menu.value=null}
async function context(event:MouseEvent,entry?:Entry,item?:TrashItem){event.preventDefault();event.stopPropagation();if(modalOpen.value)return;if(entry&&!selectedPaths.value.includes(entry.path))choose(entry);if(item)selectedTrash.value=item;if(!entry&&!item){selected.value=null;selectedPaths.value=[];selectedTrash.value=null}menuTrigger=event.currentTarget as HTMLElement;menu.value={x:Math.max(8,event.clientX),y:Math.max(8,event.clientY),blank:!entry&&!item};await nextTick();if(menuElement.value&&menu.value){const rect=menuElement.value.getBoundingClientRect();menu.value.x=Math.max(8,Math.min(menu.value.x,innerWidth-rect.width-8));menu.value.y=Math.max(8,Math.min(menu.value.y,innerHeight-rect.height-8));await nextTick();menuElement.value.querySelector<HTMLElement>('button:not(:disabled)')?.focus()}}
function overflow(event:MouseEvent){const rect=(event.currentTarget as HTMLElement).getBoundingClientRect();void contextAt(rect.left,rect.bottom,event)}
function contextAt(x:number,y:number,event:MouseEvent){const proxy={preventDefault:()=>{},stopPropagation:()=>{},clientX:x,clientY:y,currentTarget:event.currentTarget} as MouseEvent;return context(proxy,selected.value||undefined,selectedTrash.value||undefined)}
async function dispatch(id:ActionID){if(busy.value)return;
 if(readOnly.value&&['mkdir','upload','upload-folder','paste','cut','rename','move','delete','restore','purge','empty-trash'].includes(id)){dismissMenu();notify(t('files.share.readOnly'));return}
 const fromMenu=!!menu.value;const wasBlank=menu.value?.blank;const entry=selected.value;dismissMenu()
 if(id==='mkdir'||id==='rename'||id==='move'){begin(id);return}
 if(id==='open'&&entry){open(entry);return}
 if(id==='download'){download();return}
 if(id==='properties'){details.value=true;return}
 if(id==='restore'){await restore();return}
 if(id==='purge'){begin('purge');return}
 if(id==='empty-trash'){begin('empty');return}
 if(id==='favorite'){await toggleFavorite(entry);return}
 if(id==='share'){share(entry);return}
 if(id==='upload-folder'){folderInput.value?.click();return}
 if(id==='delete'){begin(root.value==='system'?'remove':'trash');return}
 if(id==='upload'){input.value?.click();return}
 if(id==='refresh'){await load();return}
 if(id==='grid'||id==='list'){setView(id);return}
 if(id==='select-all'){selectedPaths.value=display.value.map(e=>e.path);selected.value=display.value[0]||null;return}
 if(id==='copy'||id==='cut'){const items=selectedEntries.value;if(!items.length)return;if(id==='copy'&&items.some(e=>e.kind!=='file'||e.size>128*1024*1024)){notify(t('files.notice.copyLimit'));return}if(items.some(e=>e.kind==='special'||e.kind==='symlink'))return;clipboard.value={root:root.value,mode:id,entries:items.map(e=>({...e}))};notify(t(id==='copy'?'files.notice.copied':'files.notice.cut',{count:items.length}));return}
 if(id==='paste'){const clip=clipboard.value;if(!clip||clip.root!==root.value){notify(t('files.notice.pasteSameRoot'));return}if(clip.entries.length>100){notify(t('files.notice.pasteLimit'));return}busy.value=true;const destination=fromMenu&&!wasBlank&&entry?.kind==='folder'?entry.path:path.value;const destinationRoot=root.value;const failed:string[]=[];const remaining:Entry[]=[];for(const item of clip.entries){const target=[destination,item.name].filter(Boolean).join('/');if(target===item.path){failed.push(item.name+': '+t('files.notice.sameTarget'));remaining.push(item);continue}try{const result=await request<{job?:Job}>(endpoint(clip.mode==='copy'?'copy':'move',destinationRoot,item.path),{method:'POST',body:JSON.stringify({destination:target})});if(result?.job)void trackJob(item.name,destinationRoot,destination,result.job)}catch(e){failed.push(item.name+': '+message(e));remaining.push(item)}}if(clip.mode==='cut')clipboard.value=remaining.length?{...clip,entries:remaining}:null;busy.value=false;await load();if(failed.length)error.value=failed.join(' · ');else notify(t('files.notice.pasted'));return}
}
function fileKeyboard(e:KeyboardEvent){if(!appVisible())return;const target=e.target as HTMLElement;if(menu.value){if(['ArrowDown','ArrowUp','Home','End'].includes(e.key)){e.preventDefault();const nodes=[...menuElement.value!.querySelectorAll<HTMLButtonElement>('button:not(:disabled)')];const current=nodes.indexOf(document.activeElement as HTMLButtonElement);nodes[e.key==='Home'?0:e.key==='End'?nodes.length-1:(current+(e.key==='ArrowDown'?1:-1)+nodes.length)%nodes.length]?.focus()}if(e.key==='Escape'){e.preventDefault();dismissMenu();menuTrigger?.focus()}if(e.key==='Tab')dismissMenu();return}if(modalOpen.value||!appRoot.value?.contains(target)||target.closest('input,textarea,[contenteditable="true"]'))return;let id:ActionID|undefined;if(e.key==='F2')id='rename';if(e.key==='Delete'&&!trash.value)id='delete';if(e.ctrlKey||e.metaKey){id=({c:'copy',x:'cut',v:'paste',a:'select-all'} as Record<string,ActionID>)[e.key.toLowerCase()]}if((e.shiftKey&&e.key==='F10')||e.key==='ContextMenu'){e.preventDefault();const rect=target.getBoundingClientRect();void contextAt(rect.left,rect.bottom,{currentTarget:target} as unknown as MouseEvent);return}if(id){e.preventDefault();void dispatch(id)}}

</script>

<template>
 <div ref="appRoot" class="files-app" :class="{embedded:props.embedded}">
 <div v-if="user&&!host.canOpenSettings()" class="files-profile-controls" :inert="modalOpen"><label>{{t('files.settings.language')}} <select :value="host.profile.value.locale" :disabled="profileBusy" @change="updateProfile($event,'locale')"><option value="vi-VN">Tiếng Việt</option><option value="en-US">English</option></select></label><label>{{t('files.settings.theme')}} <select :value="host.profile.value.theme" :disabled="profileBusy" @change="updateProfile($event,'theme')"><option value="light">{{t('files.settings.light')}}</option><option value="dark">{{t('files.settings.dark')}}</option><option value="system">{{t('files.settings.system')}}</option></select></label></div>
