  <main v-if="!ready" class="login-wrap"><LoaderCircle class="spinning"/> {{t('files.loading')}}</main>
  <main v-else-if="user&&passwordChange" class="login-wrap"><section class="drive-login" role="alert"><span class="login-folder"><FolderOpen :size="36"/></span><h1>{{t('files.passwordChange.title')}}</h1><p>{{t('files.passwordChange.hint')}}</p><a class="primary" href="/accounts/">{{t('files.passwordChange.open')}}</a></section></main>
  <main v-else-if="!user" class="login-wrap"><section class="drive-login"><span class="login-folder"><FolderOpen :size="36"/></span><div class="eyebrow">{{t('files.login.eyebrow')}}</div><h1>{{t('files.login.title')}}</h1><p v-if="props.embedded">{{t('files.login.embeddedExpired')}}</p><template v-else><p>{{t('files.login.hint')}}</p><form @submit.prevent="login"><label>{{t('files.login.username')}}<input v-model="loginName" autocomplete="username" required maxlength="64" autofocus></label><label>{{t('files.login.password')}}<input v-model="loginPassword" type="password" autocomplete="current-password" required maxlength="256"></label><p v-if="error" role="alert" class="error">{{error}}</p><button class="primary" :disabled="loginBusy">{{loginBusy?t('files.login.busy'):t('files.login.submit')}}<ChevronRight :size="17"/></button></form></template><small><ShieldCheck :size="14"/> {{t('files.login.footer')}}</small></section></main>
  <div v-else class="drive-layout" :inert="modalOpen">
   <aside class="drive-sidebar"><span class="nav-label">{{t('files.nav.label')}}</span><template v-for="{root:item,group} in navRoots" :key="item.id"><span v-if="group" class="nav-label files-org-label">{{group}}</span><button :class="{active:root===item.id&&!trash&&special!=='recent'&&!listView}" @click="switchRoot(item.id)"><component :is="item.id==='system'?Server:item.kind==='share'?Users:Folder" :size="19"/>{{rootLabel(item)}}<span v-if="item.id==='system'" class="admin-label">{{t('files.nav.adminBadge')}}</span><span v-else-if="item.access==='read'" class="admin-label" :title="t('files.share.readOnly')"><Eye :size="12"/> {{t('files.share.readOnlyBadge')}}</span></button></template><p v-if="!roots.length" class="files-no-storage">{{t('files.roots.noneShort')}}</p><button v-if="trashRoot" :class="{active:special==='recent'}" @click="openRecent"><Clock :size="19"/>{{t('files.recent.title')}}</button><button v-if="roots.length" :class="{active:special==='favorites'}" @click="openFavorites"><Star :size="19"/>{{t('files.favorites.title')}}</button><template v-if="sharing.enabled"><button :class="{active:special==='received'||isGrant}" @click="openSharing('received')"><Inbox :size="19"/>{{t('files.received.title')}}<span v-if="received.length" class="admin-label">{{received.length}}</span></button><button :class="{active:special==='outgoing'}" @click="openSharing('outgoing')"><Share2 :size="19"/>{{t('files.outgoing.title')}}</button></template><button v-if="trashRoot" :class="{active:trash}" @click="openTrash"><Trash2 :size="19"/>{{t('files.trash.title')}}</button><div v-if="quota" class="files-quota" role="status"><span>{{t('files.quota.title')}}</span><div class="files-quota-bar"><i :class="{full:quotaPercent>=95}" :style="{width:quotaPercent+'%'}"></i></div><small>{{quota.limitBytes==null?t('files.quota.usedUnlimited',{used:quotaSize(quota.usedBytes)}):t('files.quota.used',{used:quotaSize(quota.usedBytes),limit:quotaSize(quota.limitBytes)})}}</small></div><p v-if="activityNotice" class="files-activity-notice"><Eye :size="14"/> {{t('files.activity.notice')}}</p><div class="files-sidebar-bottom"><HardDrive :size="19"/><span>{{t('files.sidebar.uploadLimit')}}</span></div></aside>
   <main class="drive-main" @dragover.prevent @drop="drop" @dragend="dragEnd">
    <div class="drive-heading"><div><span class="eyebrow">{{special==='favorites'?t('files.favorites.eyebrow'):listView||isGrant?t('files.sharing.eyebrow'):root==='system'?t('files.heading.systemEyebrow'):isShare?(current?.organization||t('files.roots.shareEyebrow')):t('files.heading.personalEyebrow')}}</span><h1>{{headingTitle}}</h1><p>{{headingHint}}</p><p v-if="quotaFolder" class="files-quota-folder" role="status">{{quotaFolder.usage.measured?t(quotaFolder.usage.limitBytes==null?'files.quotaFolder.unlimited':'files.quotaFolder.used',{path:quotaFolder.path,used:quotaSize(quotaFolder.usage.usedBytes),limit:quotaSize(quotaFolder.usage.limitBytes??0)}):t('files.quotaFolder.pending',{path:quotaFolder.path})}}</p></div><div v-if="!trash&&!special&&!readOnly&&root" class="heading-actions"><button @click="dispatch('mkdir')"><FolderPlus :size="17"/>{{t('files.actions.mkdir')}}</button><button @click="folderInput?.click()"><FolderUp :size="17"/>{{t('files.actions.uploadFolder')}}</button><button class="primary" @click="input?.click()"><Upload :size="17"/>{{t('files.actions.upload')}}</button></div><div v-else-if="trash&&trashItems.length&&!readOnly" class="heading-actions"><button class="danger-text" :disabled="busy" @click="dispatch('empty-trash')"><Trash2 :size="17"/>{{t('files.actions.emptyTrash')}}</button></div><input ref="input" type="file" multiple hidden @change="queue(($event.target as HTMLInputElement).files)"><input ref="folderInput" type="file" webkitdirectory multiple hidden @change="queue(($event.target as HTMLInputElement).files)"></div>
    <div class="drive-toolbar"><div class="navigation-actions"><button :disabled="!history.length||trash" :aria-label="t('files.toolbar.back')" @click="path=history.pop()||'';special='';load()"><ChevronLeft :size="18"/></button><button :disabled="!path||trash||listView" :aria-label="t('files.toolbar.up')" @click="navigate(crumbs.slice(0,-1).join('/'))"><ArrowUp :size="17"/></button><button :aria-label="t('files.actions.refresh')" :disabled="loading" @click="load"><RefreshCw :size="17" :class="{spinning:loading}"/></button></div><label class="file-search"><Search :size="17"/><input v-model="query" :placeholder="trash||listView?t('files.toolbar.filter'):t('files.toolbar.search')" :aria-label="t('files.toolbar.searchLabel')" @keydown.enter.prevent="runSearch"></label><div class="sort-control"><select v-model="sortKey" :aria-label="t('files.sort.label')" :disabled="trash||special==='recent'||listView"><option value="name">{{t('files.sort.name')}}</option><option value="size">{{t('files.sort.size')}}</option><option value="modified">{{t('files.sort.modified')}}</option><option value="type">{{t('files.sort.type')}}</option></select><button :aria-label="sortDesc?t('files.sort.descending'):t('files.sort.ascending')" :title="sortDesc?t('files.sort.descending'):t('files.sort.ascending')" :disabled="trash||special==='recent'||listView" @click="sortDesc=!sortDesc"><component :is="sortDesc?ArrowDown:ArrowUp" :size="16"/></button></div><label class="hidden-toggle"><input v-model="hidden" type="checkbox">{{t('files.toolbar.hidden')}}</label><div class="view-toggle"><button :aria-label="t('files.toolbar.actions')" @click="overflow"><MoreHorizontal :size="19"/></button><button :class="{chosen:view==='grid'}" :aria-label="t('files.actions.grid')" @click="setView('grid')"><Grid2X2 :size="18"/></button><button :class="{chosen:view==='list'}" :aria-label="t('files.actions.list')" @click="setView('list')"><List :size="18"/></button><button :aria-label="t('files.toolbar.details')" :aria-pressed="details" @click="details=!details"><Info :size="18"/></button></div></div>
    <div class="path-row"><div class="breadcrumbs"><button v-if="listView" @click="special==='favorites'?openFavorites():openSharing(special as 'received'|'outgoing')"><component :is="special==='favorites'?Star:special==='received'?Inbox:Share2" :size="15"/>{{headingTitle}}</button><template v-else><button :class="{'drop-target':dropTarget===''}" @click="trash?openTrash():navigate('')" @dragover="dragOver($event,'')" @dragleave="dropTarget=null" @drop="dropMove($event,'')"><component :is="trash?Trash2:root==='system'?Server:Folder" :size="15"/>{{trash?t('files.trash.title'):rootName}}</button><template v-for="(part,index) in crumbs" :key="index"><ChevronRight :size="12"/><button :class="{'drop-target':dropTarget===crumbs.slice(0,index+1).join('/')}" @click="navigate(crumbs.slice(0,index+1).join('/'))" @dragover="dragOver($event,crumbs.slice(0,index+1).join('/'))" @dragleave="dropTarget=null" @drop="dropMove($event,crumbs.slice(0,index+1).join('/'))">{{part}}</button></template><template v-if="special==='recent'||special==='search'"><ChevronRight :size="12"/><span class="crumb-view">{{special==='recent'?t('files.recent.title'):t('files.search.crumb',{query:searchTerm})}}</span></template></template><span v-if="root==='system'" class="system-path">/{{path}}</span></div><div v-if="selectedPaths.length||clipboard" class="selection-bar"><span>{{t('files.selection.count',{count:selectedPaths.length})}}</span><button :disabled="!selectedEntries.some(e=>e.kind==='file'||e.kind==='folder')" @click="dispatch('download')"><Download :size="15"/>{{t('files.actions.download')}}</button><button :disabled="busy||!selectedEntries.length||selectedEntries.some(e=>e.kind!=='file'&&e.kind!=='folder')" @click="dispatch('copy')"><Copy :size="15"/>{{t('files.actions.copy')}}</button><button :disabled="!selectedPaths.length" @click="dispatch('cut')"><Scissors :size="15"/>{{t('files.actions.cut')}}</button><button :disabled="!clipboard||clipboard.root!==root" @click="dispatch('paste')"><ClipboardPaste :size="15"/>{{t('files.actions.paste')}}</button><button :disabled="!selectedPaths.length" @click="dispatch('delete')"><Trash2 :size="15"/>{{root==='system'?t('files.selection.removePermanent'):t('files.trash.title')}}</button></div></div>
    <div v-if="error" class="error-banner" role="alert"><Info :size="17"/><span>{{error}}</span><button :aria-label="t('files.error.dismiss')" @click="error='' "><X :size="16"/></button></div><div v-if="notice" class="notice" role="status"><Check :size="16"/>{{notice}}</div>
    <div class="files-layout" :class="{'without-details':!details}"><section class="file-browser" :aria-label="t('files.browser.label')" @contextmenu="context($event)">
     <div v-if="loading" class="empty-files"><LoaderCircle class="spinning" :size="28"/><p>{{t('files.browser.loading')}}</p></div>
     <div v-else-if="!roots.length" class="empty-files"><HardDrive :size="44"/><h2>{{t('files.roots.noneTitle')}}</h2><p>{{t('files.roots.noneHint')}}</p></div>
     <template v-else-if="trash"><div v-if="!trashItems.length" class="empty-files"><Trash2 :size="40"/><h2>{{t('files.trash.empty')}}</h2></div><button v-for="item in trashItems.filter(item=>lower(item.name).includes(lower(query)))" :key="item.id" class="trash-row" @contextmenu.stop="context($event,undefined,item)" :class="{selected:selectedTrash?.id===item.id}" @click="selectedTrash=item"><File :size="23"/><span><strong>{{item.name}}</strong><small>{{t('files.trash.from',{path:item.path})}}</small></span><time :title="longDate(item.deleted)">{{shortDate(item.deleted)}}</time></button></template>
     <template v-else-if="special==='favorites'"><div v-if="!favoriteRows.length" class="empty-files"><Star :size="40"/><h2>{{t('files.favorites.empty')}}</h2><p>{{t('files.favorites.emptyHint')}}</p></div><div v-for="f in favoriteRows" :key="favoriteKey(f.root,f.path)" class="favorite-row"><button class="trash-row" @click="openFavorite(f)"><component :is="f.dir?Folder:FileText" :size="23"/><span><strong>{{baseName(f.path)}}</strong><small>{{rootLabel(findRoot(f.root))}} / {{f.path}}</small></span></button><button class="file-more" :aria-label="t('files.favorites.remove',{name:baseName(f.path)})" :title="t('files.favorites.remove',{name:baseName(f.path)})" @click="removeFavorite(f)"><X :size="17"/></button></div></template>
     <template v-else-if="special==='received'"><div v-if="!receivedRows.length" class="empty-files"><Inbox :size="40"/><h2>{{t('files.received.empty')}}</h2><p>{{t('files.received.emptyHint')}}</p></div><div v-for="g in receivedRows" :key="g.id" class="favorite-row"><button class="trash-row" @click="openReceived(g)"><component :is="g.dir?Folder:FileText" :size="23"/><span><strong>{{g.name}}</strong><small>{{t('files.received.from',{owner:g.owner})}} · {{t(g.permission==='edit'?'files.share.edit':'files.share.view')}}</small></span><time :title="longDate(g.created)">{{shortDate(g.created)}}</time></button></div></template>
     <template v-else-if="special==='outgoing'"><div v-if="!outgoingRows.length" class="empty-files"><Share2 :size="40"/><h2>{{t('files.outgoing.empty')}}</h2><p>{{t('files.outgoing.emptyHint')}}</p></div><div v-for="row in outgoingRows" :key="row.path" class="favorite-row"><button class="trash-row" @click="openOutgoing(row)"><component :is="row.dir?Folder:FileText" :size="23"/><span><strong>{{row.name}}</strong><small>{{row.path}} · {{t('files.outgoing.summary',{people:row.people,links:row.links})}}</small></span></button></div></template>
     <template v-else><div class="browser-label"><span>{{t('files.browser.count',{count:display.length})}}<template v-if="truncated&&(special==='search'||special==='recent')"> · {{t('files.search.truncated')}}</template></span><span>{{view==='grid'?t('files.browser.gridHint'):t('files.browser.listHint')}}</span></div><div v-if="!display.length" class="empty-files"><component :is="special==='recent'?Clock:FolderOpen" :size="47"/><h2>{{error?t('files.browser.unreadable'):special==='recent'?t('files.recent.empty'):query?t('files.browser.noMatch'):t('files.browser.empty')}}</h2><p v-if="!error&&special!=='recent'">{{special==='search'?t('files.search.noneHint'):query?t('files.browser.noMatchHint'):t('files.browser.emptyHint')}}</p></div><div class="file-items" :class="{rows:view==='list'}"><div v-for="entry in display" :key="entry.path" class="file-cell"><button class="file-item" :draggable="!readOnly&&entry.kind!=='special'" @dragstart="dragStart($event,entry)" @dragover="entry.kind==='folder'&&dragOver($event,entry.path)" @dragleave="dropTarget=null" @drop="entry.kind==='folder'&&dropMove($event,entry.path)" @contextmenu.stop="context($event,entry)" :class="{selected:selectedPaths.includes(entry.path),cut:clipboard?.mode==='cut'&&clipboard.root===root&&clipboard.entries.some(e=>e.path===entry.path),folder:entry.kind==='folder','drop-target':dropTarget===entry.path}" :aria-label="t('files.browser.select',{name:entry.name})" @click="choose(entry,$event)" @dblclick="open(entry)" @keydown.enter.prevent="open(entry)"><span class="file-symbol"><component :is="entry.kind==='folder'?Folder:entry.kind==='file'?FileText:Info" :size="45" :stroke-width="1.3"/><Star v-if="isFavorite(entry)" class="favorite-mark" :size="14"/><Share2 v-if="root==='personal'&&sharedPaths.has(entry.path)" class="share-mark" :size="14" :aria-label="t('files.share.badge')"/></span><span class="file-name">{{entry.name}}</span><span class="file-size">{{entry.kind==='folder'?t('files.kind.folder'):bytes(entry.size)}}</span><span class="file-mode">{{special?'/'+parentOf(entry.path):entry.mode}}</span><span class="file-date">{{shortDate(entry.modified)}}</span></button><button class="file-more" :aria-label="t('files.browser.more',{name:entry.name})" @click.stop="choose(entry);overflow($event)"><MoreHorizontal :size="18"/></button></div></div></template>
    </section>
    <aside v-if="details" class="file-inspector" :aria-label="t('files.inspector.label')"><div class="inspector-label">{{t('files.inspector.title')}} <Info :size="15"/></div><template v-if="selectedItem"><div class="inspector-preview"><component :is="!trash&&selected?.kind==='folder'?Folder:FileText" :size="54" :stroke-width="1.2"/></div><h2>{{selectedItem.name}}</h2><p class="inspector-path">{{selectedItem.path}}</p><template v-if="!trash&&selected"><dl><div><dt>{{t('files.inspector.kind')}}</dt><dd>{{t('files.kind.'+selected.kind)}}</dd></div><div><dt>{{t('files.inspector.size')}}</dt><dd>{{bytes(selected.size)}}</dd></div><div><dt>{{t('files.inspector.mode')}}</dt><dd>{{selected.mode}}</dd></div><div><dt>{{t('files.inspector.owner')}}</dt><dd>{{selected.uid}} / {{selected.gid}}</dd></div><div><dt>{{t('files.inspector.modified')}}</dt><dd>{{longDate(selected.modified)}}</dd></div></dl><div class="inspector-actions"><template v-if="selected.kind==='folder'"><button class="primary" @click="open(selected)"><FolderOpen :size="17"/>{{t('files.actions.openFolder')}}</button><button @click="dispatch('download')"><Download :size="16"/>{{t('files.actions.downloadZip')}}</button></template><button v-if="selected.kind==='file'||selected.kind==='folder'" :aria-pressed="isFavorite(selected)" @click="toggleFavorite(selected)"><Star :size="16"/>{{isFavorite(selected)?t('files.actions.unfavorite'):t('files.actions.favorite')}}</button><button v-if="sharing.enabled&&root==='personal'&&(selected.kind==='file'||selected.kind==='folder')" @click="share(selected)"><Share2 :size="16"/>{{t('files.actions.share')}}</button><template v-if="selected.kind==='file'"><button class="primary" @click="dispatch('download')"><Download :size="16"/>{{t('files.actions.download')}}</button><button :disabled="editorBusy" @click="openText(selected)"><FileText :size="16"/>{{t('files.inspector.editText')}}</button></template><template v-if="selected.kind==='file'||selected.kind==='folder'"><button :disabled="selectedPaths.length!==1||busy" @click="dispatch('rename')"><Pencil :size="16"/>{{t('files.actions.rename')}}</button><button :disabled="selectedPaths.length!==1||busy" @click="dispatch('move')"><MoveRight :size="16"/>{{t('files.inspector.move')}}</button><button class="danger-text" @click="dispatch('delete')"><Trash2 :size="16"/>{{root==='system'?t('files.inspector.removeSystem'):t('files.actions.trash')}}</button></template></div></template><div v-else class="inspector-actions"><button class="primary" @click="dispatch('restore')"><RotateCcw :size="16"/>{{t('files.actions.restore')}}</button><button v-if="trash&&!readOnly" class="danger-text" @click="dispatch('purge')"><Trash2 :size="16"/>{{t('files.actions.purge')}}</button></div></template><div v-else class="inspector-placeholder"><Folder :size="35"/><p>{{t('files.inspector.placeholder')}}</p></div></aside></div>
    <footer class="files-footer"><span>{{root==='system'?t('files.footer.system'):isGrant?t('files.footer.received'):isShare?t('files.footer.share'):t('files.footer.personal')}}</span><a v-if="root==='personal'" class="export-link" :href="exportURL" download><Download :size="15"/>{{t('files.export.link')}}</a><button :aria-expanded="showTransfers" @click="showTransfers=!showTransfers"><ArrowUpDown :size="16"/>{{t('files.transfers.button')}} <span v-if="activeTransfers">{{activeTransfers}}</span></button></footer>
   </main>
  </div>
  <section v-if="user&&showTransfers&&props.active" :inert="modalOpen" class="transfer-panel" :aria-label="t('files.transfers.title')"><header><strong>{{t('files.transfers.title')}}</strong><button :aria-label="t('files.transfers.collapse')" @click="showTransfers=false"><X :size="17"/></button></header><p v-if="!transfers.length" class="muted">{{t('files.transfers.none')}}</p><div v-for="job in transfers" :key="job.id" class="transfer-row"><component :is="job.jobId?Copy:File" :size="22"/><div><strong>{{job.name}}</strong><small v-if="job.jobId">{{jobText(job)}}</small><small v-else>{{job.status==='done'?t('files.transfers.done'):job.status==='error'?job.error:job.status==='queued'?t('files.transfers.queued'):t(job.progress===100?'files.transfers.confirming':'files.transfers.sending',{progress:job.progress})}}</small><div class="progress"><i :style="{width:job.progress+'%'}"></i></div></div><button v-if="job.jobId&&(job.status==='queued'||job.status==='uploading')" :aria-label="t('files.transfers.cancel',{name:job.name})" @click="cancelJob(job)"><X :size="17"/></button><button v-else-if="job.status==='uploading'" :aria-label="t('files.transfers.cancel',{name:job.name})" @click="job.xhr?.abort()"><X :size="17"/></button><button v-if="job.status==='error'&&job.file" :aria-label="t('files.transfers.retry',{name:job.name})" @click="startTransfer(job)"><RotateCcw :size="17"/></button><Check v-if="job.status==='done'" :size="17"/></div><p class="transfer-note">{{t('files.transfers.note')}}</p><p v-if="transfers.some(x=>x.jobId)" class="transfer-note">{{t('files.jobs.note')}}</p></section>
  <Teleport to="body"><div v-if="(action||editor||shareTarget)&&props.active" class="files-app fs-dialog-portal" :style="props.embedded?{left:dialogBounds.left+'px',top:dialogBounds.top+'px',width:dialogBounds.width+'px',height:dialogBounds.height+'px',right:'auto',bottom:'auto'}:{}"><div v-if="action" class="modal-scrim"><form class="action-dialog" role="dialog" aria-modal="true" aria-labelledby="files-action-title" @submit.prevent="submitAction"><h2 id="files-action-title">{{t('files.dialog.'+action)}}</h2><p v-if="action==='trash'||action==='remove'">{{selectedPaths.length>1?t('files.dialog.selected',{count:selectedPaths.length}):selected?.path}}<br>{{action==='remove'?t('files.dialog.removeHint'):t('files.dialog.trashHint')}}</p><p v-else-if="action==='purge'">{{selectedTrash?.name}}<br>{{t('files.dialog.purgeHint')}}</p><p v-else-if="action==='empty'">{{t('files.dialog.emptyHint',{count:trashItems.length})}}</p><label v-else>{{action==='move'?t('files.dialog.destination'):t('files.dialog.name')}}<input v-model="actionName" required maxlength="4096" autofocus></label><p v-if="error" class="error" role="alert">{{error}}</p><footer><button type="button" :disabled="busy" @click="action=null">{{t('files.dialog.cancel')}}</button><button class="primary" :disabled="busy">{{busy?t('files.dialog.busy'):t('files.dialog.confirm')}}</button></footer></form></div>
  <ShareDialog v-if="shareTarget" :path="shareTarget.path" :name="shareTarget.name" :dir="shareTarget.dir" :public-u-r-l="publicURL" :request="request" :t="t" :message="message" @close="closeShare" @changed="loadOutgoing"/>
  <div v-if="editor" class="modal-scrim"><section class="text-editor" role="dialog" aria-modal="true" :aria-label="t('files.editor.label')"><header><div><FileText :size="20"/><span><strong>{{editor.entry.name}}</strong><small>{{editor.root==='system'?t('files.editor.system'):rootLabel(findRoot(editor!.root))||rootName}} / {{editor.entry.path}}</small></span><i v-if="dirty" class="draft-dot"></i></div><button :aria-label="t('files.editor.close')" :disabled="editorBusy" @click="closeEditor"><X :size="19"/></button></header><div v-if="error" class="error-banner" role="alert">{{error}}</div><textarea v-model="editor.content" :aria-label="t('files.editor.content')" spellcheck="false" :disabled="editorBusy"></textarea><footer><span>{{t('files.editor.limits')}}</span><button class="primary" :disabled="!dirty||editorBusy" @click="saveText">{{editorBusy?t('files.editor.saving'):t('files.editor.save')}}</button></footer></section></div>
 </div></Teleport><Teleport to="body"><div v-if="menu" class="files-app fs-menu-portal"><div class="menu-dismiss" @pointerdown="dismissMenu"></div><nav ref="menuElement" class="files-context-menu" role="menu" :aria-label="t('files.toolbar.actions')" :style="{left:menu.x+'px',top:menu.y+'px'}" @contextmenu.prevent><button v-for="item in menuActions" :key="item.id" role="menuitem" :disabled="item.disabled||busy" :class="{divider:item.divider,danger:item.danger}" @click="dispatch(item.id)"><component :is="actionIcons[item.id]" :size="16"/><span>{{item.label}}</span><kbd v-if="item.shortcut">{{item.shortcut}}</kbd></button></nav></div></Teleport>
 </div>
</template>
